UPDATE user_profiles
SET
  public_info = CONCAT('Mình thích ', SUBSTRING_INDEX(SUBSTRING_INDEX(bio, ': ', -1), ' · ', 1), '. Luôn muốn tìm bạn cùng gu để nghe nhạc, đọc sách và trò chuyện.'),
  bio_visibility = 'PUBLIC',
  public_info_visibility = 'PUBLIC',
  pinned_track_visibility = 'PUBLIC'
WHERE user_id BETWEEN 1 AND 60;

